  EDMA_Init(DMA0_DMA_BASEADDR, &DMA0_config);
  (void)memset(DMA1_config.channelConfig, 0, FSL_FEATURE_EDMA_INSTANCE_CHANNELn(DMA1_DMA_BASEADDR) * sizeof(edma_channel_config_t *));
  EDMA_Init(DMA1_DMA_BASEADDR, &DMA1_config);

