  LP_FLEXCOMM3_init();
  LP_FLEXCOMM5_init();
  LP_FLEXCOMM0_init();
  LP_FLEXCOMM2_init();
  LP_FLEXCOMM6_init();
  LP_FLEXCOMM7_init();
  LP_FLEXCOMM1_init();
